	recipes.TfuiExampleAbout = react.RegisterWrapperRecipe("TfuiExampleAbout", builtin.Window, function(_params)
		return builtin.Window {
			id = "tfui_example_fr.new_window",
			title = "À propos",
			initialX = 0.1,
			initialY = 0.1,
			closable = true,
			movable = true,
			expanded = false,
			onClose = function()
				pcall(function()
					api.gui.byId.setVisible("tfui_example_fr.new_window", false)
				end)
			end,
			meta = {
				class = "tfui-example-fr-new-window-window, dialog",
			},
			content = builtin.BoxLayout {
				orientation = builtin.type.Orientation.Vertical,
				meta = {
					class = "tfui-483ae6e1",
				},
				children = {
					builtin.RichTextView {
						text = "Cette fenêtre est un exemple créé avec TFUI, l’éditeur d’interface pour Transport Fever 3.\n\nToutes les valeurs affichées sont fictives : aucune logique n’est branchée.",
						meta = {
							class = "tfui-fb9d8955",
						},
					},
					builtin.BoxLayout {
						orientation = builtin.type.Orientation.Horizontal,
						children = {
							builtin.Component {
								meta = {
									class = "horizontal-spacer",
								},
							},
							builtin.Button {
								onClick = function()
					pcall(function()
						api.gui.byId.setVisible("tfui_example_fr.new_window", false)
					end)
				end,
								meta = {
									class = "primary, tfui-9ebeda80",
								},
								content = builtin.TextView {
									text = "OK",
									meta = {
										class = "tfui-7cf01da2",
									},
								},
							},
						},
					},
				},
			},
		}
	end)
	
	recipes.TfuiExampleFrModButton = react.RegisterPluginRecipe(main_mod_button_area.MainModButtonAreaExtension, "TfuiExampleFrModButton", function(_params)
		return builtin.BoxLayout {
			orientation = builtin.type.Orientation.Horizontal,
			children = {
				builtin.Button {
					onClick = function()
					local wapi = game_react_globals.getDefaultWindowApi()
					if wapi == nil then
						return
					end
					wapi.addSingletonWindow(recipes.TfuiExampleFrMainWindow, {})
					pcall(function()
						api.gui.byId.setVisible("tfui_example_fr.main", true)
					end)
					wapi.moveSingletonWindowToFront(recipes.TfuiExampleFrMainWindow)
				end,
					meta = {
						class = "secondary",
						tooltip = "TFUI — Exemple",
					},
					content = builtin.TextView {
						text = "TFUI — Exemple",
						meta = {
							class = "font-scale-body",
						},
					},
				},
			},
		}
	end)
	
	return {
		TfuiExampleFrMainWindow = recipes.TfuiExampleFrMainWindow,
		TfuiExampleAbout = recipes.TfuiExampleAbout,
		TfuiExampleFrModButton = recipes.TfuiExampleFrModButton,
	}
